from pathlib import Path

def r(path,old,new):
    p=Path(path); s=p.read_text()
    if old not in s: raise SystemExit('missing in '+path+': '+old[:120])
    p.write_text(s.replace(old,new,1))

r('src/components/InstructorAccountControls.tsx',
  "function singleTriggerRuntimeLabel(value: DynamicScenarioTrigger) {\n  if (value.type === 'manual') return 'Manual'\n  if (value.type === 'time') return `After ${value.seconds}s`\n  if (value.type === 'condition') return `${value.metric} ${value.operator === 'lt' ? '<' : value.operator === 'gt' ? '>' : '='} ${value.value}`\n  return `${String(value.parameter)} changed · ${value.actor}`\n}\nfunction triggerRuntimeLabel(triggers: DynamicScenarioTrigger[]) { return triggers.map(singleTriggerRuntimeLabel).join(' OR ') }\n",
  '')
r('src/components/InstructorAccountControls.tsx',
  "            <div><span>Stage time</span><strong>{formatStageTimer(stageElapsedSeconds)}</strong></div>\n            <div><span>Trigger</span><strong>{triggerRuntimeLabel(triggers)}</strong></div>\n",
  "            <div><span>Stage time</span><strong>{formatStageTimer(stageElapsedSeconds)}</strong></div>\n")
r('src/account.css',
  ".dynamic-runtime-stage-card { display: grid; grid-template-columns: minmax(0,1.3fr) minmax(70px,.45fr) minmax(82px,.5fr) minmax(0,1.25fr); gap: 1px; background: #263a43; border: 1px solid #263a43; }",
  ".dynamic-runtime-stage-card { display: grid; grid-template-columns: minmax(0,1.5fr) minmax(82px,.55fr) minmax(96px,.65fr); gap: 1px; background: #263a43; border: 1px solid #263a43; }")

